select case when s.rating >= 3.6 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end as rating_bucket, max(ss.units) - min(ss.units) as units_range, count(*) as store_sale_count from store_sales ss left join products p on p.id = ss.product_id right join suppliers s on s.id = p.supplier_id where ss.revenue >= 2300 group by case when s.rating >= 3.6 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end;
